import numpy as np
def equation(t, x, v, params):
    w=np.pi/10
    return (params[0] + params[1]*x*np.exp(-x) + params[2]*v + params[3]*v*np.exp(-x)
            + params[4]*np.cos(w*t) + params[5]*np.sin(w*t) + params[6]*v**2 + params[7]*x
            + params[8]*x**2 + params[9]*x**3)
